@isTest
private class OpportunityWonHandlerTest {

    private static final String WON = 'Closed Won';
    private static final String HANDOVER = 'Handover to Customer Success';

    // ─── BEFORE INSERT ───────────────────────────────────────────────────────────

    @isTest
    static void beforeInsert_wonOpportunity_setsNextStep() {
        Opportunity opp = new Opportunity(
            Name = 'Win Deal',
            StageName = WON,
            CloseDate = Date.today().addDays(30)
        );
        insert opp;

        Opportunity fresh = [SELECT NextStep, StageName FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(HANDOVER, fresh.NextStep, 'NextStep must be set on newly won insert');
        System.assertEquals(WON, fresh.StageName);
    }

    @isTest
    static void beforeInsert_notWonOpportunity_doesNotSetNextStep() {
        Opportunity opp = new Opportunity(
            Name = 'Early Stage',
            StageName = 'Prospecting',
            CloseDate = Date.today().addDays(60)
        );
        insert opp;

        Opportunity fresh = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertNotEquals(HANDOVER, fresh.NextStep, 'NextStep must NOT be set for non-won insert');
    }

    // ─── BEFORE UPDATE ───────────────────────────────────────────────────────────

    @isTest
    static void beforeUpdate_toWon_setsNextStep() {
        Opportunity opp = createNonWonOpportunity();
        insert opp;

        opp.StageName = WON;
        update opp;

        Opportunity fresh = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(HANDOVER, fresh.NextStep, 'NextStep must be set when updated to Closed Won');
    }

    @isTest
    static void beforeUpdate_alreadyWon_doesNotCreateExtraTask() {
        Opportunity opp = new Opportunity(
            Name = 'Already Won',
            StageName = WON,
            CloseDate = Date.today().addDays(30)
        );
        insert opp;

        System.assertEquals(1, countTasks(opp.Id), 'Expect 1 task after initial won insert');

        opp.Amount = 9999;
        update opp;

        System.assertEquals(1, countTasks(opp.Id), 'No additional task for editing an already-won opp');
    }

    @isTest
    static void beforeUpdate_fromWonToOtherStage_doesNotResetNextStep() {
        Opportunity opp = new Opportunity(
            Name = 'Won Then Lost',
            StageName = WON,
            CloseDate = Date.today().addDays(30)
        );
        insert opp;

        opp.StageName = 'Prospecting';
        update opp;

        Opportunity fresh = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals(HANDOVER, fresh.NextStep,
