public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException(
                'Object and field API names must not be null or blank.');
        }

        Schema.SObjectType objectType = findObjectType(objectApiName);
        if (objectType == null) {
            throw new PicklistServiceException(
                'Object not found: ' + objectApiName);
        }

        Schema.DescribeFieldResult fieldDescribe = findField(objectType, fieldApiName);
        if (fieldDescribe == null) {
            throw new PicklistServiceException(
                'Field not found: ' + fieldApiName + ' on object: ' + objectType.getDescribe().getName());
        }

        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.Picklist
         && fieldType != Schema.DisplayType.MultiPicklist) {
            throw new PicklistServiceException(
                'Field ' + fieldDescribe.getName() + ' is not a picklist or multi-select picklist. Actual type: ' + fieldType);
        }

        List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues(true);

        Object rawDefault = fieldDescribe.getDefaultValue();
        String defaultValue = (rawDefault != null) ? (String) rawDefault : null;

        List<Option> result = new List<Option>();
        if (entries != null) {
            for (Schema.PicklistEntry entry : entries) {
                if (entry.isActive()) {
                    result.add(new Option(
                        entry.getValue(),
                        entry.getLabel(),
                        entry.getValue() == defaultValue
                    ));
                }
            }
        }

        return result;
    }

    private static Schema.SObjectType findObjectType(String apiName) {
        Map<String, Schema.SObjectType> globalMap = Schema.getGlobalDescribe();
        String target = apiName.toUpperCase();
        for (String key : globalMap.keySet()) {
            if (key.toUpperCase() == target) {
                return globalMap.get(key);
            }
        }
        return null;
    }

    private static Schema.DescribeFieldResult findField(Schema.SObjectType objectType, String apiName) {
        Map<String, Schema.SObjectField> fieldMap = objectType.getDescribe().fields.getMap();
        String target = apiName.toUpperCase();
        for (String key : fieldMap.keySet()) {
            if (key.toUpperCase() == target) {
                return fieldMap.get(key).getDescribe();
            }
        }
        return null;
    }
}
