public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> s) {
            return new Opportunities(
                new Map<fflib_SObjectDomain.HandlerContext, fflib_ISObjectDomain>{
                    fflib_SObjectDomain.HandlerContext.AFTER_INSERT  => new AfterInsertHandler(),
                    fflib_SObjectDomain.HandlerContext.AFTER_UPDATE  => new AfterUpdateHandler()
                }
            );
        }
    }

    private final IOpportunityFulfilmentService service;

    private Opportunities(Map<fflib_SObjectDomain.HandlerContext, fflib_ISObjectDomain> handlers) {
        super(handlers);
        this.service = (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
    }

    private class AfterInsertHandler implements fflib_ISObjectDomain {
        public void handle() {
            Set<Id> qualifyingIds = new Set<Id>();
            for (Opportunity opp : (List<Opportunity>) Trigger.new) {
                if (opp.StageName == 'Closed Won') {
                    qualifyingIds.add(opp.Id);
                }
            }
            if (!qualifyingIds.isEmpty()) {
                service.startFulfilment(qualifyingIds);
            }
        }
    }

    private class AfterUpdateHandler implements fflib_ISObjectDomain {
        public void handle() {
            List<Opportunity> newOpps = (List<Opportunity>) Trigger.new;
            List<Opportunity> oldOpps = (List<Opportunity>) Trigger.old;
            Set<Id> qualifyingIds = new Set<Id>();
            for (Integer i = 0; i < newOpps.size(); i++) {
                if (newOpps[i].StageName == 'Closed Won' && oldOpps[i].StageName != 'Closed Won') {
                    qualifyingIds.add(newOpps[i].Id);
                }
            }
            if (!qualifyingIds.isEmpty()) {
                service.startFulfilment(qualifyingIds);
            }
        }
    }
}
