public virtual class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public Constructor() {
        }

        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    public Opportunities(List<SObject> records) {
        super(records);
    }

    public override void validate(List<SObject> records) {
        for (Opportunity opp : (List<Opportunity>) records) {

            // Rule 1: Amount must not be negative (insert and update)
            if (opp.Amount != null && opp.Amount < 0) {
                this.error('Amount cannot be negative.', opp, Opportunity.Amount);
            }

            // Rule 2: Amount cannot change on an opportunity already Closed Won (update only)
            if (Trigger.isUpdate) {
                Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);
                if (oldOpp.StageName == 'Closed Won' && oldOpp.Amount != opp.Amount) {
                    this.error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                }
            }
        }
    }
}
