public with sharing class ErpCustomerSync {

    /**
     * Enqueues one Queueable job per newly-created account.
     * Each job performs a single POST callout to the ERP.
     */
    public static void enqueue(List<Account> accounts) {
        for (Account acct : accounts) {
            System.enqueueJob(new SyncJob(acct.Id, acct.Name, acct.BillingCountry));
        }
    }

    public class SyncJob implements Queueable {

        private final Id accountId;
        private final String name;
        private final String country;

        public SyncJob(Id accountId, String name, String country) {
            this.accountId = accountId;
            this.name      = name;
            this.country   = country;
        }

        public void execute(QueueableContext ctx) {
            Map<String, Object> customer = new Map<String, Object>{
                'salesforceId' => accountId,
                'name'         => name,
                'country'      => String.isBlank(country) ? null : country
            };

            HttpRequest req = new HttpRequest();
            req.setEndpoint('callout:ERP/api/customers');
            req.setMethod('POST');
            req.setHeader('Content-Type', 'application/json');
            req.setBody(JSON.serialize(new List<Map<String, Object>>{ customer }));
            req.setTimeout(60000);

            // Error handling and retries are out of scope for this ticket.
            new Http().send(req);
        }
    }
}
