public with sharing class LineItemDiscountHandler {

    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        // 1. Collect only the Product2Ids that actually need a lookup.
        Set<Id> productIdsNeeded = new Set<Id>();
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIdsNeeded.add(line.Product2Id);
            }
        }

        if (productIdsNeeded.isEmpty()) {
            return;
        }

        // 2. Single SOQL to fetch Family for every distinct product.
        Map<Id, String> familyByProductId = new Map<Id, String>();
        for (Product2 p : [
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIdsNeeded
        ]) {
            familyByProductId.put(p.Id, p.Family);
        }

        // 3. Apply the standard discount via PricingRules (rules stay in one place).
        //    Use containsKey so we still call the method when Family is null;
        //    standardDiscountForFamily handles null by returning 0.
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                if (familyByProductId.containsKey(line.Product2Id)) {
                    line.Discount = PricingRules.standardDiscountForFamily(
                        familyByProductId.get(line.Product2Id)
                    );
                }
            }
        }
    }
}
