public with sharing class LeadContactMatcher {

    /**
     * For each lead (in order), returns the Id of the first contact whose email
     * matches the lead's email (case-insensitive, trimmed), or null if there is
     * no match or the lead's email is blank.
     *
     * @param leads    Leads to match (order is preserved in the result).
     * @param contacts Candidate contacts; first match in list order wins.
     * @return List<Id> same size as leads.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        // Phase 1 – build a normalized-email → first-contact-Id index
        Map<String, Id> contactByEmail = new Map<String, Id>();
        for (Contact c : contacts) {
            if (c.Email == null) {
                continue;
            }
            String key = normalize(c.Email);
            if (key == '') {
                continue;
            }
            // Keep only the first contact seen for a given email
            if (!contactByEmail.containsKey(key)) {
                contactByEmail.put(key, c.Id);
            }
        }

        // Phase 2 – resolve each lead in order
        List<Id> results = new List<Id>();
        for (Lead l : leads) {
            if (l.Email == null) {
                results.add(null);
            } else {
                String key = normalize(l.Email);
                results.add(key == '' ? null : contactByEmail.get(key));
            }
        }
        return results;
    }

    /**
     * Trims and lower-cases an email so that '  Foo@Bar.COM ' and 'foo@bar.com'
     * produce the same key.
     */
    private static String normalize(String email) {
        return email.trim().toLowerCase();
    }
}
