public class RenewalReminderService {

    /**
     * Sends a renewal-reminder email to the owner of each given opportunity.
     * 
     * NOTE: Messaging.sendEmail is called once per opportunity inside the loop.
     * The governor limit allows at most 10 sendEmail calls per transaction,
     * so this method will throw LimitExceeded if more than 10 opportunities
     * are processed. For the stated 200-opportunity batch, consider batching
     * emails into a single sendEmail call (up to 1000 per call, 10 calls per
     * transaction) to stay within limits.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Name, CloseDate, OwnerId
             FROM Opportunity
             WHERE Id IN :opportunityIds]
        );

        Integer sentCount = 0;

        for (Id oppId : opportunityIds) {
            Opportunity opp = oppMap.get(oppId);
            if (opp == null || opp.OwnerId == null) {
                continue;
            }

            try {
                Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
                mail.setTargetObjectId(opp.OwnerId);
                mail.setSaveAsActivity(false);
                mail.setSubject('Renewal due: ' + opp.Name);
                mail.setPlainTextBody(buildBody(opp));

                Messaging.SendEmailResult[] results =
                    Messaging.sendEmail(new Messaging.SingleEmailMessage[] { mail });

                if (results != null && results.size() == 1 && results[0].isSuccess()) {
                    sentCount++;
                }
            } catch (Exception e) {
                // Individual email failed; log and continue
                System.debug('RenewalReminderService: failed to send reminder for '
                    + opp.Name + ' (' + oppId + '): ' + e.getMessage());
            }
        }

        return sentCount;
    }

