const COLUMNS = [
    { fieldName: 'Name', label: 'Name' },
    { fieldName: 'StageName', label: 'Stage' },
    { fieldName: 'Amount', label: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' }
            ]
        }
    }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    @api opportunities;

    get columns() {
        return COLUMNS;
    }

    handleRowAction(event) {
        const { action, row } = event.detail;

        switch (action.name) {
            case 'view':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: { recordId: row.Id, actionName: 'view' }
                });
                break;
            case 'edit':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: { recordId: row.Id, actionName: 'edit' }
                });
                break;
            case 'delete':
                this.handleDelete(row);
                break;
        }
    }

    handleDelete(row) {
        LightningConfirm.open({
            label: 'Confirm Delete',
            message: `Are you sure you want to delete "${row.Name}"?`,
            confirmLabel: 'Delete',
            cancelLabel: 'Cancel'
        }).then((confirmed) => {
            if (!confirmed) return;

            deleteRecord(row.Id)
                .then(() => {
                    this.opportunities = this.opportunities.filter(
                        (opp) => opp.Id !== row.Id
                    );
                    this.showToast('Opportunity deleted', 'The opportunity has been deleted.', 'success');
                })
                .catch((error) => {
                    const message =
                        error.body && error.body.message
                            ? error.body.message
                            : 'An unexpected error occurred.';
                    this.showToast('Delete failed', message, 'error');
                });
        });
    }

    showToast(title, message, variant) {
        const event = new CustomEvent('showtoast', {
            bubbles: true,
            composed: true,
            detail: { title, message, variant }
        });
        this.dispatchEvent(event);
    }
}
