import { LightningElement, track } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    @track stats = null;
    @track error = null;

    _isRequestInFlight = false;
    _pollingInterval = null;

    _onVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            this._startPolling();
        } else {
            this._stopPolling();
        }
    };

    connectedCallback() {
        document.addEventListener('visibilitychange', this._onVisibilityChange);
        if (document.visibilityState === 'visible') {
            this._startPolling();
        }
    }

    disconnectedCallback() {
        this._stopPolling();
        document.removeEventListener('visibilitychange', this._onVisibilityChange);
    }

    _startPolling() {
        this._stopPolling();
        this._fetchStats();
        this._pollingInterval = setInterval(() => {
            this._fetchStats();
        }, 60000);
    }

    _stopPolling() {
        if (this._pollingInterval !== null) {
            clearInterval(this._pollingInterval);
            this._pollingInterval = null;
        }
    }

    async _fetchStats() {
        if (this._isRequestInFlight) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            return;
        }

        this._isRequestInFlight = true;
        try {
            const result = await getQueueStats();
            this.stats = result;
            this.error = null;
        } catch (err) {
            this.error = err.body.message;
        } finally {
            this._isRequestInFlight = false;
        }
    }
}
