public class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // ── Validation ──────────────────────────────────────────────────────────

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('percentByGauId must not be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' must not be null.');
            }
            if (pct <= 0) {
                throw new AllocationException('Percentage for GAU ' + gauId + ' must be greater than 0.');
            }
            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'Percentages total ' + totalPercent + '%, which exceeds 100%.');
        }

        // Verify every GAU exists and is active
        Set<Id> gauIds = percentByGauId.keySet();
        Map<Id, npsp__General_Accounting_Unit__c> gauMap =
            new Map<Id, npsp__General_Accounting_Unit__c>(
                [SELECT Id, Name, npsp__Active__c
                 FROM npsp__General_Accounting_Unit__c
                 WHERE Id IN :gauIds]
            );

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauMap.get(gauId);
            if (gau == null) {
                throw new AllocationException('GAU ' + gauId + ' was not found.');
            }
            if (!gau.npsp__Active__c) {
                throw new AllocationException('GAU "' + gau.Name + '" is not active.');
            }
        }

        // ── Read opportunity amount (for initial allocation amounts) ────────────

        Opportunity opp = [SELECT Id, Amount FROM Opportunity WHERE Id = :opportunityId];
        Decimal oppAmount = (opp.Amount != null) ? opp.Amount : 0;

        // ── Delete existing allocations ─────────────────────────────────────────

        List<npsp__Allocation__c> existingAllocs = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocs.isEmpty()) {
            delete existingAllocs;
        }

        // ── Insert new allocations ──────────────────────────────────────────────
        // Setting npsp__Percent__c ensures NPSP's standard automation
        // recalculates npsp__Amount__c whenever the opportunity amount changes.

        List<npsp__Allocation__c> newAllocs = new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            npsp__Allocation__c alloc = new npsp__Allocation__c(
                npsp__Opportunity__c            = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c                = pct,
                npsp__Amount__c                 = oppAmount * pct / 100
            );
            newAllocs.add(alloc);
        }

        insert newAllocs;

        return newAllocs;
    }
}
