    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // Resolve the NPSP Household Account record type by DeveloperName (no hard-coded Id)
        String hhRecordTypeId = [
            SELECT Id
            FROM RecordType
            WHERE SObjectType = 'Account'
              AND DeveloperName = 'HH_Account'
            WITH USER_MODE
        ].Id;

        // Create the household account without setting Name –
        // NPSP's Account/Contact triggers will generate the household name automatically
        Account hh = new Account(RecordTypeId = hhRecordTypeId);
        insert hh;

        // Link every member to the new household and persist in one DML statement
        for (Contact c : members) {
            c.AccountId = hh.Id;
        }
        insert members;

        // Designate the first contact as the household's primary contact
        hh.npe01__One2OneContact__c = members[0].Id;
        update hh;

        return hh.Id;
    }
}
