public class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // --- Validation (before any DML) ---

        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be at least 1.');
        }

        Opportunity opp = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
        ];

        if (opp.IsClosed) {
            throw new PaymentPlanException('Opportunity is closed.');
        }

        // --- Fetch existing payments ---

        List<npe01__OppPayment__c> allPayments = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        // --- Separate history (paid / written-off) from deletable payments ---

        Decimal settledAmount = 0;
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c p : allPayments) {
            Boolean isPaid = (p.npe01__Paid__c == true);
            Boolean isWrittenOff = (p.npe01__Written_Off__c == true);

            if (isPaid || isWrittenOff) {
                Decimal amt = (p.npe01__Payment_Amount__c != null)
                    ? p.npe01__Payment_Amount__c : 0;
                settledAmount += amt;
            } else {
                toDelete.add(p);
            }
        }

        // --- Compute outstanding ---

        Decimal oppAmount = (opp.Amount != null) ? opp.Amount : 0;
        Decimal outstanding = oppAmount - settledAmount;

        if (outstanding <= 0) {
            throw new PaymentPlanException('Outstanding amount is not greater than zero.');
        }

        // --- Build new payment records ---

        Decimal baseAmount = outstanding.divide(numberOfPayments, 2, RoundingMode.DOWN);

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c(
                npe01__Opportunity__c    = opportunityId,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c           = false
            );

            if (i < numberOfPayments - 1) {
                payment.npe01__Payment_Amount__c = baseAmount;
            } else {
                // Last payment absorbs the remainder
                payment.npe01__Payment_Amount__c =
                    outstanding - (baseAmount * (numberOfPayments - 1));
            }

            newPayments.add(payment);
        }

        // --- DML ---

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }

        insert newPayments;

        return newPayments;
    }
}
