public with sharing class FamilyService {

    /**
     * Creates NPSP Parent relationships for the given child-to-parent mappings.
     * Idempotent: skips any pair that already has a relationship in either direction.
     *
     * @param parentIdByChildId  Keys = child Contact Id, Values = parent Contact Id.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect every unique contact id that appears in the map
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            if (childId != null) {
                allContactIds.add(childId);
            }
            Id parentId = parentIdByChildId.get(childId);
            if (parentId != null) {
                allContactIds.add(parentId);
            }
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // Single SOQL: fetch all existing relationships that touch any of our contacts
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
               OR npe4__RelatedContact__c IN :allContactIds
        ]) {
            if (rel.npe4__Contact__c != null && rel.npe4__RelatedContact__c != null) {
                existingPairs.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
            }
        }

        // Build the list of new relationship records to insert
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null) {
                continue;
            }

            // Skip if a relationship already exists in either direction
            if (existingPairs.contains(pairKey(childId, parentId))
             || existingPairs.contains(pairKey(parentId, childId))) {
                continue;
            }

            // Child is the primary contact; type 'Parent' means
            // "the related contact is my Parent."
            // NPSP's reciprocal trigger (List Setting) automatically
            // creates the inverse record on the parent side with the
            // correct reciprocal type (Son / Daughter / Child) based
            // on the child's gender.
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c         = childId,
                npe4__RelatedContact__c  = parentId,
                npe4__Type__c            = 'Parent',
                npe4__Status__c          = 'Current'
            ));
        }

        // Single DML: bulk insert all new relationships at once
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /**
     * Builds a deterministic composite key representing a directed pair.
     */
    private static String pairKey(Id a, Id b) {
        return a + ':' + b;
    }
}
