public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final Integer FOLLOW_UP_DAYS = 3;

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        if (newlist == null || newlist.isEmpty()) {
            return null;
        }

        List<Task> tasksToCreate = new List<Task>();

        if (Trigger.isInsert) {
            for (SObject so : newlist) {
                Opportunity opp = (Opportunity) so;
                if (isMajorGift(opp)) {
                    tasksToCreate.add(buildTask(opp));
                }
            }
        }
        else if (Trigger.isUpdate) {
            if (oldlist == null || oldlist.isEmpty()) {
                return null;
            }
            for (Integer i = 0; i < newlist.size(); i++) {
                Opportunity newOpp = (Opportunity) newlist[i];
                Opportunity oldOpp = (Opportunity) oldlist[i];
                if (isMajorGift(newOpp) && !isMajorGift(oldOpp)) {
                    tasksToCreate.add(buildTask(newOpp));
                }
            }
        }

        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }

        return null;
    }

    private static Boolean isMajorGift(Opportunity opp) {
        return opp.StageName != null
            && opp.StageName.equals(STAGE_CLOSED_WON)
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    private static Task buildTask(Opportunity opp) {
        Task t = new Task();
        t.Subject  = 'Major gift thank-you call';
        t.Priority = 'High';
        t.Status   = 'Not Started';
        t.WhatId   = opp.Id;
        t.WhoId    = opp.npsp__Primary_Contact__c;
        t.OwnerId  = opp.OwnerId;
        if (opp.CloseDate != null) {
            t.ActivityDate = opp.CloseDate.addDays(FOLLOW_UP_DAYS);
        }
        return t;
    }
}
